module movie_theme (\n    input clk,\n    input rst_n,\n    input in_start,\n    input in_valid,\n    input [31:0] in_data,\n    output reg out_done,\n    output reg out_possible\n);\n\n    // State definitions\n    localparam [4:0] IDLE          = 5'd0;\n    localparam [4:0] READ_F        = 5'd1;\n    localparam [4:0] READ_T        = 5'd2;\n    localparam [4:0] READ_N        = 5'd3;\n    localparam [4:0] READ_START    = 5'd4;\n    localparam [4:0] READ_END      = 5'd5;\n    localparam [4:0] COMPUTE       = 5'd6;\n    localparam [4:0] DP_LOOP       = 5'd7;\n    localparam [4:0] CHECK_RESULT  = 5'd8;\n    localparam [4:0] NEXT_FREQ     = 5'd9;\n    localparam [4:0] DONE          = 5'd10;\n\n    // Constants\n    localparam [31:0] MAX_FREQ      = 32'd10;\n    localparam [31:0] MAX_INTERVAL  = 32'd100;\n\n    // Registers\n    reg [4:0] state;\n    reg [31:0] f;\n    reg [31:0] freq_count;\n    reg [31:0] current_t;\n    reg [31:0] current_n;\n    reg [31:0] interval_count;\n    reg [31:0] L_array [0:99];\n    reg [31:0] H_array [0:99];\n    reg [31:0] gap_array [0:99];\n    reg [31:0] prev_end;\n    reg [31:0] temp_start;\n    reg overall_possible;\n    reg skip_dp;\n    reg dp_plus;\n    reg dp_minus;\n    reg [31:0] i;\n\n    integer k; // Loop variable for array initialization\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            out_done <= 1'b0;\n            out_possible <= 1'b0;\n            f <= 32'd0;\n            freq_count <= 32'd0;\n            current_t <= 32'd0;\n            current_n <= 32'd0;\n            interval_count <= 32'd0;\n            prev_end <= 32'd0;\n            temp_start <= 32'd0;\n            overall_possible <= 1'b1;\n            skip_dp <= 1'b0;\n            dp_plus <= 1'b0;\n            dp_minus <= 1'b0;\n            i <= 32'd0;\n\n            // Array initialization\n            for (k = 0; k < 100; k = k + 1) begin\n                L_array[k] <= 32'd0;\n                H_array[k] <= 32'd0;\n                gap_array[k] <= 32'd0;\n            end\n        end else begin\n            unique case (state)\n                IDLE: begin\n                    out_done <= 1'b0;\n                    if (in_start) begin\n                        state <= READ_F;\n                        overall_possible <= 1'b1;\n                        freq_count <= 32'd0;\n                    end\n                end\n\n                READ_F: begin\n                    if (in_valid) begin\n                        f <= in_data;\n                        state <= READ_T;\n                    end\n                end\n\n                READ_T: begin\n                    if (in_valid) begin\n                        current_t <= in_data;\n                        state <= READ_N;\n                    end\n                end\n\n                READ_N: begin\n                    if (in_valid) begin\n                        current_n <= in_data;\n                        interval_count <= 32'd0;\n                        skip_dp <= 1'b0;\n                        state <= READ_START;\n                    end\n                end\n\n                READ_START: begin\n                    if (in_valid) begin\n                        temp_start <= in_data;\n                        state <= READ_END;\n                    end\n                end\n\n                READ_END: begin\n                    if (in_valid) begin\n                        L_array[interval_count] <= in_data - temp_start;\n                        H_array[interval_count] <= current_t - (in_data - temp_start);\n\n                        if ((in_data - temp_start) > current_t) begin\n                            skip_dp <= 1'b1;\n                            overall_possible <= 1'b0;\n                        end\n\n                        if (interval_count > 32'd0) begin\n                            gap_array[interval_count-32'd1] <= temp_start - prev_end;\n                        end\n\n                        prev_end <= in_data;\n                        interval_count <= interval_count + 32'd1;\n\n                        if ((interval_count + 32'd1) < current_n) begin\n                            state <= READ_START;\n                        end else begin\n                            state <= COMPUTE;\n                        end\n                    end\n                end\n\n                COMPUTE: begin\n                    if (skip_dp) begin\n                        state <= NEXT_FREQ;\n                    end else if (current_n == 32'd1) begin\n                        state <= NEXT_FREQ;\n                    end else begin\n                        dp_plus <= 1'b1;\n                        dp_minus <= 1'b1;\n                        i <= 32'd0;\n                        state <= DP_LOOP;\n                    end\n                end\n\n                DP_LOOP: begin\n                    if (i < (current_n - 32'd1)) begin\n                        // Compatibility checks\n                        reg comp_pp, comp_mm;\n                        comp_pp = (L_array[i] <= H_array[i+32'd1]);\n                        comp_mm = (L_array[i+32'd1] <= H_array[i]);\n\n                        // Update DP states\n                        dp_plus <= (dp_plus && comp_pp) || (dp_minus && (gap_array[i] >= 32'd1));\n                        dp_minus <= (dp_plus && (gap_array[i] >= 32'd1)) || (dp_minus && comp_mm);\n\n                        i <= i + 32'd1;\n                    end else begin\n                        state <= CHECK_RESULT;\n                    end\n                end\n\n                CHECK_RESULT: begin\n                    if (!(dp_plus || dp_minus)) begin\n                        overall_possible <= 1'b0;\n                    end\n                    state <= NEXT_FREQ;\n                end\n\n                NEXT_FREQ: begin\n                    freq_count <= freq_count + 32'd1;\n                    if (freq_count < (f - 32'd1)) begin\n                        state <= READ_T;\n                    end else begin\n                        state <= DONE;\n                    end\n                end\n\n                DONE: begin\n                    out_done <= 1'b1;\n                    out_possible <= overall_possible;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule